-- In-app + push notifications, generated by database triggers rather than
-- by individual API routes. Orders change status from ~10 different code
-- paths (Stripe webhook, ship/pickup/receipt routes, the pickup cron,
-- admin refunds, DOA claims) and wiring a notification call into each one
-- is exactly how "review received" ended up never notifying anyone. A
-- trigger on the table can't be skipped by any code path.
--
-- notify_user() does two things: inserts a notifications row (the app
-- receives it instantly over Supabase Realtime and shows it in the phone's
-- notification bar) and fires the remote Expo push via pg_net (async, so
-- it never slows down the write that triggered it).

create extension if not exists pg_net;

create table notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles (id) on delete cascade,
  type text not null,
  title text not null,
  body text not null,
  data jsonb not null default '{}'::jsonb,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_created_idx on notifications (user_id, created_at desc);
create index notifications_user_unread_idx on notifications (user_id) where read_at is null;

alter table notifications enable row level security;
-- Select-own only: needed so Realtime delivers a user's own rows to them.
-- Writes go through triggers (security definer) and the service-role API.
create policy notifications_select_own on notifications for select using (user_id = auth.uid());

alter publication supabase_realtime add table notifications;

create or replace function notify_user(p_user_id uuid, p_type text, p_title text, p_body text, p_data jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_messages jsonb;
begin
  insert into notifications (user_id, type, title, body, data)
  values (p_user_id, p_type, p_title, p_body, coalesce(p_data, '{}'::jsonb));

  select jsonb_agg(jsonb_build_object(
    'to', token,
    'title', p_title,
    'body', p_body,
    'data', coalesce(p_data, '{}'::jsonb) || jsonb_build_object('type', p_type),
    'sound', 'default',
    'channelId', 'default'
  ))
  into v_messages
  from push_tokens
  where user_id = p_user_id;

  if v_messages is not null then
    perform net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := v_messages,
      headers := '{"Content-Type": "application/json", "Accept": "application/json"}'::jsonb
    );
  end if;
exception when others then
  -- A notification failure must never abort the order/message/review
  -- write that triggered it.
  raise warning 'notify_user failed for %: %', p_user_id, sqlerrm;
end;
$$;

-- ── New message → recipient ───────────────────────────────────────────
create or replace function trg_notify_new_message()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recipient uuid;
  v_sender_name text;
begin
  select case when c.user_a_id = new.sender_id then c.user_b_id else c.user_a_id end
  into v_recipient
  from conversations c
  where c.id = new.conversation_id;

  select display_name into v_sender_name from profiles where id = new.sender_id;

  if v_recipient is not null then
    perform notify_user(
      v_recipient,
      'message',
      coalesce(nullif(v_sender_name, ''), 'New message'),
      left(new.content, 140),
      jsonb_build_object('conversationId', new.conversation_id)
    );
  end if;
  return new;
end;
$$;

create trigger on_message_inserted_notify
  after insert on messages
  for each row execute function trg_notify_new_message();

-- ── Order status changes → whichever side needs to know ───────────────
create or replace function trg_notify_order_status()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_data jsonb := jsonb_build_object('orderId', new.id);
  v_title text := new.listing_title;
begin
  if old.status is not distinct from new.status then
    return new;
  end if;

  if new.status = 'confirmed' and old.status = 'pending' then
    perform notify_user(new.seller_id, 'order', 'You made a sale! 🎉', 'Someone just ordered "' || v_title || '".', v_data);
    perform notify_user(new.buyer_id, 'order_status', 'Order confirmed ✅', 'Your payment for "' || v_title || '" went through.', v_data);
  elsif new.status = 'shipped' then
    perform notify_user(new.buyer_id, 'order_status', 'Your order shipped 📦', '"' || v_title || '" is on its way.', v_data);
  elsif new.status = 'delivered' then
    perform notify_user(new.buyer_id, 'order_status', 'Delivered', '"' || v_title || '" was delivered.', v_data);
  elsif new.status = 'awaiting_pickup' then
    perform notify_user(new.buyer_id, 'order_status', 'Ready for pickup 📍', 'The seller marked "' || v_title || '" as picked up — please confirm.', v_data);
  elsif new.status = 'completed' then
    perform notify_user(new.seller_id, 'order_status', 'Payment released 💰', 'Funds for "' || v_title || '" are on their way to your bank.', v_data);
  elsif new.status = 'cancelled' and old.status <> 'pending' then
    perform notify_user(new.seller_id, 'order_status', 'Order cancelled', 'The order for "' || v_title || '" was cancelled.', v_data);
    perform notify_user(new.buyer_id, 'order_status', 'Order cancelled', 'Your order for "' || v_title || '" was cancelled.', v_data);
  elsif new.status = 'refunded' then
    perform notify_user(new.buyer_id, 'order_status', 'Refund issued', 'You were refunded for "' || v_title || '".', v_data);
    perform notify_user(new.seller_id, 'order_status', 'Order refunded', 'The order for "' || v_title || '" was refunded.', v_data);
  elsif new.status = 'doa_claim' then
    perform notify_user(new.seller_id, 'order_status', 'DOA claim filed', 'The buyer filed a DOA claim for "' || v_title || '".', v_data);
  end if;

  return new;
end;
$$;

create trigger on_order_status_notify
  after update of status on orders
  for each row execute function trg_notify_order_status();

-- ── New review → seller ───────────────────────────────────────────────
create or replace function trg_notify_new_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_reviewer_name text;
begin
  select display_name into v_reviewer_name from profiles where id = new.reviewer_id;
  perform notify_user(
    new.seller_id,
    'review',
    'New review ' || repeat('⭐', new.rating),
    coalesce(nullif(v_reviewer_name, ''), 'A buyer') || ' left you a ' || new.rating || '-star review.',
    jsonb_build_object('listingId', new.listing_id)
  );
  return new;
end;
$$;

create trigger on_review_inserted_notify
  after insert on reviews
  for each row execute function trg_notify_new_review();
